import{_ as e,c as t,o as r,a6 as o,aX as s,aY as n}from"./chunks/framework.B2XPZL2i.js";const h=JSON.parse('{"title":"前言","description":"网站的前言📝","frontmatter":{"top":1,"description":"网站的前言📝","tag":["酷安"],"// sidebar":false},"headers":[],"relativePath":"coolapk/index.md","filePath":"coolapk/index.md"}'),i={name:"coolapk/index.md"};function p(d,a,c,l,_,g){return r(),t("div",{"data-pagefind-body":!0},a[0]||(a[0]=[o('<h1 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to “前言”">​</a></h1><p>因为本人改过的控制中心太多了，时间久了版本太乱了，就想着搞一篇能 <strong>持续更新</strong>、<strong>分类筛选</strong>，且能 <strong>呈现修改时间轴</strong> 的汇总贴。本来应该在酷安内开这篇整理贴的，但是酷安的图文编辑次数有限，而且关键是删文章会扣经验，就把这篇文章托管在第三方了。</p><p>现在正在使用的是 Vitepress（主题🎨<a href="https://theme.sugarat.top/" target="_blank" rel="noreferrer">@sugarat/theme</a>），可以直接编写足够清晰美观的时间轴，来呈现我的修改日志。</p><p>顺便写段<strong>个人介绍</strong>：<br>本人在酷安目前主要是折腾各种安卓应用逆向，包括前端图标绘制、布局调整，以及一些简单的逻辑处理。主玩粮厂的高仿iOS，力争改出全网最强的 <strong>高仿iOS控制中心</strong>。偶尔也会做些小设计、写些小项目；所有动态、图文在左侧侧边栏都有整理。</p><h4 id="打赏作者" tabindex="-1">打赏作者 <a class="header-anchor" href="#打赏作者" aria-label="Permalink to “打赏作者”">​</a></h4><blockquote><p>小站维护不易，请我一杯可乐呗 (´͈ ᵕ `͈ )~</p></blockquote><img src="'+s+'" alt="打赏图" class="reward-img"><img src="'+n+'" alt="打赏图" class="reward-img">',8)]))}const f=e(i,[["render",p]]);export{h as __pageData,f as default};
